import { installTwinCharacter } from './twin-character.mjs';
import { parseDialogue } from './dialogue.mjs';
import { OPENING_SCENARIO,OPENING_VERSION,OPENING_PHONE_MESSAGES } from './opening.mjs';
import { phoneIcon } from '../phone-v2/icons.mjs';
import { waitMotion } from '../ui/serial-motion.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPENING_SIGNATURE=JSON.stringify(parseDialogue(OPENING_SCENARIO));
const STEPS={install:{title:'不请自来的图标',text:'手机正在自行安装催眠APP。先观察屏幕上的变化。',action:'welcome'},phone:{title:'你的手机',text:'点击桌宠，再从周围圆圈打开手机。横屏与竖屏都可以阅读。',selector:'[aria-label="打开手机"]',action:'point'},message:{title:'一条陌生消息',text:'手机中的“消息”已经收到双胞胎联络员的邀请。点开手机，再进入消息。',selector:'[aria-label="打开手机"]',action:'think'},locations:{title:'跟着路线走',text:'地点窗口用于探索区域与前往目的地。查看区域与当前位置，选择想去的地方。移动不会占用日程格。',selector:'[aria-label="打开地点"]',action:'point'},notebook:{title:'人物与线索',text:'笔记保存你认识的人。调查前的资料会保留空白，照片可换，长内容会续页。',selector:'[aria-label="打开笔记"]',action:'welcome'},schedule:{title:'行动真正发生的时刻',text:'将行动与备注安排在今天的日程格。推进选中区间后才送给剧情。',selector:'.player-schedule',action:'point'},services:{title:'测试用户服务',text:'工作间的应用服务，可办理VIP、能量与上限福利。选择后加入日程，送出并确认办理才结算。',selector:'[data-location-service="app-services"]',action:'think'},finish:{title:'从现在开始，由你决定',text:'教程结束。读完最后一句后，对话框会收起；底栏的日志入口始终保留。',action:'celebrate'}};
export async function installTutorialWorld(runtime,twins){const locations=await runtime.store.listObjects('location'),world=locations.find(x=>x.id==='map-world'),school=locations.find(x=>x.id==='map-school'),street=locations.find(x=>x.name==='商业街');
 const ensure=async object=>{if(!await runtime.store.getObject(object))await runtime.saveLocationDefinition(object);};
 const gate={kind:'location',id:'tutorial-school-gate',name:'旧校舍后门',data:{description:'旧校舍旁普通的侧门。',mapScope:'school'},children:[],features:[],ui:{sceneBackground:'tutorial/backgrounds/school-gate.png'}};
 const workshop={kind:'location',id:'twins-workshop',name:'书店二楼工作室',data:{description:'书店咖啡馆二楼，双胞胎的普通小工作室。',mapScope:'world'},children:[],features:[],ui:{sceneBackground:'tutorial/backgrounds/twins-workshop.png'}};
 for(const location of [gate,workshop])await ensure(location);for(const [parent,child]of [[school??world,gate],[street??world,workshop]])if(parent&&!parent.children.some(x=>x.id===child.id)){parent.children.push({kind:'location',id:child.id});await runtime.saveLocationDefinition(parent);}
 for(const location of locations){if(location.name==='商业街'||location.id==='lin-an-office'){location.ui.sceneBackground='tutorial/backgrounds/'+(location.id==='lin-an-office'?'detective-office':'commercial-street')+'.png';await runtime.saveLocationDefinition(location);}}
 await installTwinCharacter(runtime,twins);
}
export async function mountOpeningTutorial({scene,store,contacts,assetBase,onFinished=()=>{},onContactKnown=async()=>{}}){
 const doc=scene.root.ownerDocument,win=doc.defaultView;let state=await store.readJson('ui/opening-tutorial.json',{version:OPENING_VERSION,seen:[],complete:false}),current='',node=null,spotlight=null,destroyed=false,busy=false,epoch=0;
 const style=doc.createElement('style');style.textContent=`.tutorial-card{position:fixed;right:max(20px,var(--hypno-scene-right,20px));top:calc(var(--hypno-scene-top,60px) + 18px);z-index:130;max-width:300px;width:28vw;min-width:220px;display:flex;gap:10px;align-items:flex-end;pointer-events:auto;font:12px/1.8 system-ui;color:#e9d9e8}.tutorial-mascot{width:80px;height:130px;object-fit:contain;flex:none;filter:drop-shadow(0 6px 8px #1a14234d)}.tutorial-copy{background:linear-gradient(140deg,#443349e8,#252434e8);border:1px solid #d9b9c55c;border-radius:18px;padding:13px 15px;box-shadow:0 10px 35px #0003;backdrop-filter:blur(10px)}.tutorial-copy small{font-size:9px;color:#caadc5;letter-spacing:1px}.tutorial-copy strong{display:block;color:#e9cfb7;font-size:13px}.tutorial-copy p{margin:6px 0;font-size:11px}.tutorial-copy button{border:0;border-radius:9px;background:#967b9e;color:#f6e8f0;padding:5px 10px;font:11px system-ui;cursor:pointer}.tutorial-focus{position:fixed;pointer-events:none;border:2px solid #e6c597;border-radius:12px;box-shadow:0 0 0 9999px #11101d24,0 0 25px #e4ba9755;z-index:120}.tutorial-install{position:fixed;inset:0;z-index:250;display:grid;place-items:center;background:#11131c85;backdrop-filter:blur(8px);pointer-events:none}.tutorial-mini-phone{width:170px;height:350px;border:5px solid #0e0e14;border-radius:33px;padding:26px 14px;box-sizing:border-box;background:radial-gradient(at 50% 20%,#745677,#272335);box-shadow:0 15px 70px #0007;color:#e9dae9;text-align:center;font:12px system-ui;position:relative}.tutorial-mini-phone:before{content:'';position:absolute;width:58px;height:14px;border-radius:20px;background:#09090d;left:50%;transform:translateX(-50%);top:8px}.tutorial-mini-phone>small{display:block;margin:10px 0 50px;color:#baabc4}.tutorial-install-icon{margin:auto;width:58px;height:58px;display:grid;place-items:center;border-radius:17px;background:linear-gradient(140deg,#c6a9ec,#735093);position:relative}.tutorial-install-icon .ip-icon{width:34px;height:34px}.tutorial-progress{position:absolute;inset:-5px;border:3px solid #e9dbe933;border-top-color:#f4e0f0;border-radius:21px}.tutorial-mini-phone p{font-size:11px;margin-top:15px;color:#d0b8d9}@media(max-width:700px){.tutorial-card{top:calc(var(--hypno-scene-top,80px) + 8px);right:14px;max-width:270px;width:65vw}.tutorial-mascot{width:62px;height:98px}.tutorial-copy{padding:9px 12px}.tutorial-copy p{font-size:10px}.tutorial-copy strong{font-size:12px}}`;doc.head.append(style);
 if(state.version!==OPENING_VERSION)state={version:OPENING_VERSION,seen:[],complete:false};
 const save=()=>store.writeJson('ui/opening-tutorial.json',state);function clear(){node?.remove();node=null;spotlight?.remove();spotlight=null;}
 async function installation(){const overlay=doc.createElement('section');overlay.className='tutorial-install floating-surface';overlay.innerHTML=`<div class="tutorial-mini-phone"><small>08:25</small><div class="tutorial-install-icon">${phoneIcon('hypnosis')}<i class="tutorial-progress"></i></div><p>催眠APP · 安装中</p></div>`;doc.body.append(overlay);const phone=overlay.querySelector('.tutorial-mini-phone'),ring=overlay.querySelector('.tutorial-progress');if(phone.animate)await waitMotion(phone.animate([{opacity:0,translate:'0 30px',scale:.85},{opacity:1,translate:'0 0',scale:1}],{duration:280,easing:'ease-out'}));if(ring.animate)await waitMotion(ring.animate([{rotate:'0deg'},{rotate:'360deg'}],{duration:1400,easing:'ease-in-out'}));ring.remove();overlay.querySelector('p').textContent='安装完成';await new Promise(r=>win.setTimeout(r,400));if(phone.animate)await waitMotion(phone.animate([{opacity:1},{opacity:0,translate:'0 -15px'}],{duration:220}));overlay.remove();}
 function focus(selector){spotlight?.remove();if(!selector)return;let target=scene.root.querySelector(selector)??doc.querySelector(selector);let rect=target?.getBoundingClientRect();if(!rect||rect.width<1||rect.height<1){target=doc.querySelector('.dp-pet');rect=target?.getBoundingClientRect();}if(!rect)return;spotlight=doc.createElement('i');spotlight.className='tutorial-focus';spotlight.style.cssText=`left:${rect.left-4}px;top:${rect.top-4}px;width:${rect.width+8}px;height:${rect.height+8}px`;doc.body.append(spotlight);}
 return{state,async frame(frame,playback){if(destroyed||playback.historical||playback.floor?.id!=='0'||playback.floor?.signature!==OPENING_SIGNATURE)return;if(!frame.guide||current===frame.guide||state.complete)return;const version=++epoch;current=frame.guide;clear();const step=STEPS[current];if(!step)return;if(current==='install'&&!state.seen.includes('install')){busy=true;try{await installation();}finally{busy=false;}if(version!==epoch||destroyed)return;}if(current==='message')await onContactKnown('hacker-twins');if(current==='notebook')await onContactKnown('lin-an');if(current==='services')await onContactKnown('twins-services');if(current==='message')for(const message of OPENING_PHONE_MESSAGES)await contacts.authorizeTutorialMessage(message.contactId,message.text,message.id);state.seen.push(current);await save();node=doc.createElement('aside');node.className='tutorial-card floating-surface';node.innerHTML=`<img class="tutorial-mascot" src="${assetBase+'tutorial/lin-an-'+step.action+'.png'}" alt="林安教程小人"><div class="tutorial-copy"><small>FIRST CONTACT</small><strong>${esc(step.title)}</strong><p>${esc(step.text)}</p><button data-understood>知道了</button></div>`;node.querySelector('button').addEventListener('click',clear);doc.body.append(node);focus(step.selector);},canContinue(){return !busy;},async finish(){if(state.complete)return;epoch++;clear();state.complete=true;await save();await onFinished();},destroy(){destroyed=true;epoch++;clear();style.remove();}};
}
